effect.shader:
vec2 distorcer(vec2 p, float coef) {
    float r2 = dot(p, p);
    float f = 1.0 + k1 * r2 + k2 * r2 * r2;
    return p * (f + coef);
}

void main() {
    vec2 p = acScreenNorm - center;
    p.x *= acAspect;
    vec2 pr = distorcer(p,  chroma);
    vec2 pg = distorcer(p,  0.0);
    vec2 pb = distorcer(p, -chroma);
    pr.x /= acAspect; pg.x /= acAspect; pb.x /= acAspect;
    float r = texture(inputImg, pr + center).r;
    float g = texture(inputImg, pg + center).g;
    float b = texture(inputImg, pb + center).b;
    float a = texture(inputImg, pg + center).a;
    fragColor = vec4(r, g, b, a);
}
